contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address adr, bytes memory data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        uint256 beforeBalance = address(c).balance;
        c.Command{value: 0}(adr, data); if (__ESBMC_reverted()) return;
        uint256 afterBalance = address(c).balance;
        assert(afterBalance <= beforeBalance);
    }
}

